      const [min, max] = CACTUS_HEIGHTS[count - 1];
      const parts = Array.from({ length: count }, (_, i) => ({
        dx: i * 18,
        h: min + Math.floor(Math.random() * (max - min + 1)),
      }));
      obstacles.push({ type: "cactus", x: W + 10, y: 0, w: 18 * count - 4, h: 0, parts });
