    if (event.code === "Space" || event.code === "ArrowUp") {
      event.preventDefault();
      if (!event.repeat) jump();
    } else if (event.code === "ArrowDown") {
      event.preventDefault();
      duckHeld = true;
    } else if (event.code === "Enter" && !running && !event.target.closest("a")) {
      jump();
    }
  });
