      obstacleBoxes(o).some((b) => d.x < b.x + b.w && d.x + d.w > b.x && d.y < b.y + b.h && d.y + d.h > b.y),
    );
  }

  function update(k) {
    speed = Math.min(15, 6 + score / 400);
    score += speed * 0.1 * k;
    dino.vy += (GRAVITY + (!dino.onGround && duckHeld ? FAST_FALL : 0)) * k;
    dino.y += dino.vy * k;
    if (dino.y >= GROUND - DINO_H) {
      dino.y = GROUND - DINO_H;
      dino.vy = 0;
      dino.onGround = true;
    }
    legTick += k;
    if (legTick >= 6) {
      legTick = 0;
      legFrame = 1 - legFrame;
    }
