      g.x -= speed * k;
      if (g.x + g.w < 0) {
        g.x += W + 40;
        g.w = 6 + Math.random() * 18;
      }
    });
    if (hit()) {
      running = false;
      best = Math.max(best, Math.floor(score));
    }
  }

  function drawDino() {
    ctx.fillStyle = colors.accent;
    if (isDucking()) {
      const y = GROUND - DUCK_H;
      drawSprite(duckBody, dino.x, y);
      drawSprite(duckLegs[legFrame], dino.x + 3 * PX, y + duckBody.length * PX);
