      }
    });
  }

  function drawCactus(c) {
    c.parts.forEach((part) => {
      const x = c.x + part.dx;
      const y = GROUND - part.h;
      ctx.fillRect(x + 4, y, 6, part.h);
      ctx.fillRect(x + 5, y - 2, 4, 2);
      const leftY = y + Math.round(part.h * 0.4);
