  const body = [
    ".........#####........",
    "........#######.......",
    ".......###.#####......",
    ".......#########......",
    ".......########.......",
    ".......####...........",
    "#......####...........",
    "#.....########........",
    "###..######..#........",
    ".##########...........",
    ".##########...........",
    "..#########...........",
    "...#######............",
    "....#####.............",
];

const legs = [
  [
    "....##.##.....",
    "....#..#......",
    "....#..##.....",
    "....##........",
  ],
  [
    "....##.##.....",
    "....#..#.....",
    "....##.#......",
    ".......##.....",
  ],
];

  const duckBody = [
"......................",
"......................",
"......................",
"...............#####..",
"..............#######.",
".............###.#####",
".............#########",
"###.........#########.",
"..###....#######......",
"...#############......",
"...###############....",
"....###########..#....",
".....########.........",
"......######..........",
];

