    ctx.textAlign = "center";
    ctx.fillStyle = colors.accent;
    if (!started) ctx.fillText(t.start, W / 2, H / 2 - 20);
    else if (!running) ctx.fillText(t.over, W / 2, H / 2 - 20);
  }

